(function(){
  try {
    function queryDeep(selector) {
      for (const el of document.querySelectorAll('*')) {
        if (el.shadowRoot) {
          const found = el.shadowRoot.querySelector(selector);
          if (found) return found;
        }
      }
      return document.querySelector(selector);
    }

    const fields = {
      '#field-name': 'Jane Smith',
      '#field-address': '123 Test Lane',
      '#field-city': 'Anytown',
      '#field-zip': '00000',
      '#field-card': '4111111111111111',
      '#field-expiry': '12/28',
      '#field-cvv': '123'
    };

    for (const [sel, val] of Object.entries(fields)) {
      let input = document.querySelector(sel);
      if (!input) {
        for (const el of document.querySelectorAll('*')) {
          if (el.shadowRoot) {
            const found = el.shadowRoot.querySelector(sel);
            if (found) { input = found; break; }
          }
        }
      }
      if (input) {
        input.value = val;
        input.dispatchEvent(new Event('input', { bubbles: true }));
        input.dispatchEvent(new Event('change', { bubbles: true }));
      }
    }

    const btn = document.querySelector('#place-order-btn') || queryDeep('#place-order-btn');
    if (btn) {
      btn.click();
      return 'Successfully filled form and clicked place order!';
    }
    return 'Filled form but place order button not found';
  } catch(e) {
    return 'Error: ' + e.message;
  }
})()
